// coding-misk · Neon Ascent
// song composed with sections and tracks: each track plays its clips, switched on by the section lane (1 plays, 0 is silent, values in between fade)
// each .analyze("…") lights up its instrument in the Stage visual
setcpm(128/4)

const SECTIONS = [['Crescendo', 15], ['Crescendo 2', 33], ['Intro', 4], ['Build', 8], ['Drop', 8], ['Break', 4], ['Drop 2', 8], ['Stop', 8]]
const TEMPO = {'Crescendo': 128, 'Crescendo 2': 128, 'Intro': 128, 'Build': 128, 'Drop': 128, 'Break': 128, 'Drop 2': 128, 'Stop': 128}

// section lanes: 1 plays, 0 is silent, values in between fade
const section1 = "<1!15 0!73>"  // Crescendo · 15 bars · 128 BPM · A · Am
const section2 = "<0!15 1!33 0!40>"  // Crescendo 2 · 33 bars · 128 BPM · A · Am F C G
const section3 = "<0!48 1!4 0!36>"  // Intro · 4 bars · 128 BPM · A · Am F C G
const section4 = "<0!52 1!8 0!28>"  // Build · 8 bars · 128 BPM · A · Am F C G
const section5 = "<0!60 1!8 0.5 0!19>"  // Drop · 8 bars · 128 BPM · A · Am F C G
const section6 = "<0!68 0.5 1!3 0!16>"  // Break · 4 bars · 128 BPM · A · Am F C G · fades in over 1 bars
const section7 = "<0!72 1!8 0!8>"  // Drop 2 · 8 bars · 128 BPM · A · Am F C G
const section8 = "<0!80 1!8>"  // Stop · 8 bars · 128 BPM · A · Am F C G

// ========== drums ==========
// Crescendo · bars 1-15 · pattern C~3
// Drums · RolandTR909
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR909").gain(0.9).lpf(2000).mask(section1).velocity(section1).orbit(1).analyze("kick")
$: s("~ [cp ~ ~ ~] ~ [cp ~ ~ ~]").bank("RolandTR909").gain(0.72).lpf(2000).mask(section1).velocity(section1).orbit(1).analyze("snare")
$: s("[hh ~ ~ ~] ~ ~ ~").bank("RolandTR909").gain(0.45).lpf(2000).mask(section1).velocity(section1).orbit(1).analyze("hats")
// Crescendo 2 · bars 16-48 · pattern C~3
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR909").gain(0.9).lpf(2000).mask(section2).velocity(section2).orbit(1).analyze("kick")
