$: s("[hh ~ ~ ~] ~ ~ ~").bank("RolandTR909").gain(0.45).lpf(2000).mask(section2).velocity(section2).orbit(1).analyze("hats")
// Intro · bars 49-52 · pattern A~3
$: s("[~ ~ oh ~] ~ ~ [~ ~ oh ~]").bank("RolandTR909").gain(0.41).lpf(2000).mask(section3).velocity(section3).orbit(1).analyze("hats")
// Build · bars 53-60 · pattern B~3
